def convergentHullFiniteRange (R : X →L[𝕜] C(OnePoint ℕ, Y)) (m : ℕ) :
    Submodule 𝕜 C(OnePoint ℕ, Y) :=
  ⨆ k : Fin (m + 1), LinearMap.range ((convergentFreeze (𝕜 := 𝕜) (Y := Y) k.val).comp R).toLinearMap

